# Source register definitions. Fields:
# id, citation, year, doi, url, type, pop, instr, level, design, access, flag, origin, recs (pass record keys / elicit rows)
PR='peer-reviewed empirical'; MA='meta-analysis'; SR='systematic review'; BK='book'; TH='thesis'; PP='preprint'; PRAC='practitioner'; MKT='marketing'; VID='video'; OT='other'
S=[]
def s(id,citation,year,doi,url,type,pop,instr,level,design,access,flag,origin,recs=''):
    S.append(dict(source_id=id,citation=citation,year=year,doi=doi,url=url,source_type=type,population=pop,instrument=instr,skill_level=level,design=design,access=access,quality_flag=flag,origin=origin,origin_records=recs))

